-- Webmail schema.
--
-- This file is the authoritative DDL. `webmail.dbml` is the readable model of
-- the same schema, kept alongside it for review and diagrams.
--
-- It is NOT generated by `dbml-tools tosql`: that generator emits foreign keys
-- without their ON DELETE / ON UPDATE actions, and this schema depends on
-- ON DELETE CASCADE throughout. See docs/adr/0012-schema-in-dbml.md.
--
-- Tables are singular snake_case. Canonical content lives in the g_* tables;
-- every other table carrying a customer_id is a per-user projection of one.

SET NAMES utf8mb4;
SET foreign_key_checks = 0;

DROP TABLE IF EXISTS `alias`;
CREATE TABLE `alias` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `customer_id` (`customer_id`),
  KEY `mailbox_id` (`mailbox_id`),
  CONSTRAINT `alias_ibfk_3` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE,
  CONSTRAINT `alias_ibfk_4` FOREIGN KEY (`customer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `audit_log`;
CREATE TABLE `audit_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) DEFAULT NULL,
  `user_id` bigint(20) DEFAULT NULL,
  `username` varchar(255) NOT NULL,
  `is_admin` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `operation` enum('insert','update','delete') NOT NULL,
  `entity` varchar(255) NOT NULL,
  `identifier` varchar(255) NOT NULL,
  `changes_before` text NOT NULL,
  `changes_after` text NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `user_id` (`user_id`),
  KEY `entity` (`entity`),
  KEY `created_at` (`created_at`),
  CONSTRAINT `audit_logs_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `audit_logs_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `attachment`;
CREATE TABLE `attachment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `message_id` bigint(20) NOT NULL,
  `g_attachment_id` bigint(20) NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `message_id` (`message_id`),
  KEY `g_attachment_id` (`g_attachment_id`),
  CONSTRAINT `attachment_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attachment_ibfk_2` FOREIGN KEY (`message_id`) REFERENCES `message` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attachment_ibfk_3` FOREIGN KEY (`g_attachment_id`) REFERENCES `g_attachment` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `chat`;
CREATE TABLE `chat` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  `g_chat_id` bigint(20) NOT NULL,
  `last_read_message_id` bigint(20) DEFAULT NULL,
  `muted` tinyint(1) NOT NULL DEFAULT 0,
  `notification_preference` enum('all','mentions_only','none') NOT NULL DEFAULT 'all',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `mailbox_id` (`mailbox_id`),
  KEY `g_chat_id` (`g_chat_id`),
  KEY `last_read_message_id` (`last_read_message_id`),
  CONSTRAINT `chat_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_ibfk_2` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_ibfk_3` FOREIGN KEY (`g_chat_id`) REFERENCES `g_chat` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_ibfk_4` FOREIGN KEY (`last_read_message_id`) REFERENCES `g_chat_message` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `chat_message`;
CREATE TABLE `chat_message` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `chat_id` bigint(20) NOT NULL,
  `g_chat_message_id` bigint(20) NOT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `chat_id` (`chat_id`),
  KEY `g_chat_message_id` (`g_chat_message_id`),
  CONSTRAINT `chat_message_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_message_ibfk_2` FOREIGN KEY (`chat_id`) REFERENCES `chat` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_message_ibfk_3` FOREIGN KEY (`g_chat_message_id`) REFERENCES `g_chat_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `contact`;
CREATE TABLE `contact` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_id_email` (`customer_id`,`email`),
  FULLTEXT KEY `name` (`name`),
  FULLTEXT KEY `email` (`email`),
  CONSTRAINT `contact_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `customer`;
CREATE TABLE `customer` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `default_mailbox_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `default_mailbox_id` (`default_mailbox_id`),
  CONSTRAINT `customer_ibfk_1` FOREIGN KEY (`default_mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `domain`;
CREATE TABLE `domain` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `customer_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `domain_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `email_template`;
CREATE TABLE `email_template` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `language` varchar(2) NOT NULL,
  `sender_name` varchar(255) NOT NULL,
  `sender_email` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `body` text NOT NULL,
  `parameters` text NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `language_name` (`language`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `folder`;
CREATE TABLE `folder` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `mailbox_id` (`mailbox_id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `folder_ibfk_3` FOREIGN KEY (`customer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `folder_ibfk_4` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_attachment`;
CREATE TABLE `g_attachment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_message_id` bigint(20) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `mime_type` varchar(255) NOT NULL,
  `file_size` int(11) NOT NULL,
  `hash_md5` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `thread_id` (`g_message_id`),
  CONSTRAINT `g_attachment_ibfk_1` FOREIGN KEY (`g_message_id`) REFERENCES `g_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_chat`;
CREATE TABLE `g_chat` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `type` enum('direct','group') NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `created_by_email` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_chat_attachment`;
CREATE TABLE `g_chat_attachment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_chat_message_id` bigint(20) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `mime_type` varchar(255) NOT NULL,
  `file_size` int(11) NOT NULL,
  `hash_md5` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `g_chat_message_id` (`g_chat_message_id`),
  CONSTRAINT `g_chat_attachment_ibfk_1` FOREIGN KEY (`g_chat_message_id`) REFERENCES `g_chat_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_chat_message`;
CREATE TABLE `g_chat_message` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_chat_id` bigint(20) NOT NULL,
  `sender_email` varchar(255) NOT NULL,
  `sender_name` varchar(255) NOT NULL,
  `body` mediumtext NOT NULL,
  `body_html` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `edited_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `g_chat_id` (`g_chat_id`),
  FULLTEXT KEY `sender_name` (`sender_name`),
  FULLTEXT KEY `body` (`body`),
  CONSTRAINT `g_chat_message_ibfk_1` FOREIGN KEY (`g_chat_id`) REFERENCES `g_chat` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_chat_participant`;
CREATE TABLE `g_chat_participant` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_chat_id` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `role` enum('creator','admin','member') NOT NULL,
  `joined_at` datetime NOT NULL DEFAULT current_timestamp(),
  `left_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `g_chat_id` (`g_chat_id`),
  CONSTRAINT `g_chat_participant_ibfk_1` FOREIGN KEY (`g_chat_id`) REFERENCES `g_chat` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_attendee`;
CREATE TABLE `g_attendee` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_meeting_id` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `will_attend` enum('yes','no','maybe') NOT NULL DEFAULT 'maybe',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `g_meeting_id` (`g_meeting_id`),
  CONSTRAINT `g_attendee_ibfk_1` FOREIGN KEY (`g_meeting_id`) REFERENCES `g_meeting` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_document`;
CREATE TABLE `g_document` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_meeting_id` bigint(20) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `mime_type` varchar(255) NOT NULL,
  `file_size` int(11) NOT NULL,
  `hash_md5` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `g_meeting_id` (`g_meeting_id`),
  CONSTRAINT `g_document_ibfk_1` FOREIGN KEY (`g_meeting_id`) REFERENCES `g_meeting` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_meeting`;
CREATE TABLE `g_meeting` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_schedule` bigint(20) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `time_zone` varchar(255) NOT NULL,
  `is_all_day` tinyint(1) NOT NULL DEFAULT 0,
  `organizer_email` varchar(255) NOT NULL,
  `organizer_name` varchar(255) NOT NULL,
  `description` mediumtext NOT NULL,
  `description_html` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `g_schedule` (`g_schedule`),
  CONSTRAINT `g_meeting_ibfk_1` FOREIGN KEY (`g_schedule`) REFERENCES `g_schedule` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_message`;
CREATE TABLE `g_message` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_thread_id` bigint(20) NOT NULL,
  `sender_email` varchar(255) NOT NULL,
  `sender_name` varchar(255) NOT NULL,
  `body` mediumtext NOT NULL,
  `body_html` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `g_thread_id` (`g_thread_id`),
  FULLTEXT KEY `sender_name` (`sender_name`),
  FULLTEXT KEY `body` (`body`),
  CONSTRAINT `g_message_ibfk_7` FOREIGN KEY (`g_thread_id`) REFERENCES `g_thread` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_schedule`;
CREATE TABLE `g_schedule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `time_zone` varchar(255) NOT NULL,
  `repeat_rule` mediumtext NOT NULL,
  `recurrence_dates` mediumtext NOT NULL,
  `exception_dates` mediumtext NOT NULL,
  `repeat_rule_human_readable` varchar(255) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_subscription`;
CREATE TABLE `g_subscription` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_thread_id` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `g_thread_id` (`g_thread_id`),
  CONSTRAINT `g_subscription_ibfk_1` FOREIGN KEY (`g_thread_id`) REFERENCES `g_thread` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `g_thread`;
CREATE TABLE `g_thread` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `subject_line` varchar(255) NOT NULL,
  `body_summary` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  FULLTEXT KEY `subject_line` (`subject_line`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `inbound_email`;
CREATE TABLE `inbound_email` (
  `provider_id` varchar(255) NOT NULL,
  `received_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`provider_id`),
  KEY `received_at` (`received_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `mailbox`;
CREATE TABLE `mailbox` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `user_id` bigint(20) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `color` varchar(255) NOT NULL,
  `default_folder_id` bigint(20) DEFAULT NULL,
  `default_alias_id` bigint(20) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `inbox_folder_id` (`default_folder_id`),
  KEY `default_alias_id` (`default_alias_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `mailbox_ibfk_6` FOREIGN KEY (`default_folder_id`) REFERENCES `folder` (`id`) ON DELETE SET NULL,
  CONSTRAINT `mailbox_ibfk_7` FOREIGN KEY (`default_alias_id`) REFERENCES `alias` (`id`) ON DELETE SET NULL,
  CONSTRAINT `mailbox_ibfk_8` FOREIGN KEY (`customer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mailbox_ibfk_9` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `notification_preference`;
CREATE TABLE `notification_preference` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `frequency` enum('daily_digest','hourly_digest') NOT NULL DEFAULT 'daily_digest',
  `quiet_hours_start` time DEFAULT NULL,
  `quiet_hours_end` time DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `notification_preference_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `meeting`;
CREATE TABLE `meeting` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `g_meeting_id` bigint(20) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  `schedule_id` bigint(20) DEFAULT NULL,
  `will_attend` enum('yes','no','maybe') DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `g_meeting_id` (`g_meeting_id`),
  KEY `mailbox_id` (`mailbox_id`),
  KEY `schedule_id` (`schedule_id`),
  CONSTRAINT `meeting_ibfk_10` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `meeting_ibfk_11` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE,
  CONSTRAINT `meeting_ibfk_12` FOREIGN KEY (`schedule_id`) REFERENCES `schedule` (`id`),
  CONSTRAINT `meeting_ibfk_8` FOREIGN KEY (`g_meeting_id`) REFERENCES `g_meeting` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `reminder_event`;
CREATE TABLE `reminder_event` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  `g_meeting_id` bigint(20) NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `mailbox_id` (`mailbox_id`),
  KEY `g_meeting_id` (`g_meeting_id`),
  KEY `scheduled_at` (`scheduled_at`),
  KEY `sent_at` (`sent_at`),
  CONSTRAINT `reminder_event_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reminder_event_ibfk_2` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reminder_event_ibfk_3` FOREIGN KEY (`g_meeting_id`) REFERENCES `g_meeting` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `thread_id` bigint(20) NOT NULL,
  `g_message_id` bigint(20) NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `thread_id` (`thread_id`),
  KEY `g_message_id` (`g_message_id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `message_ibfk_6` FOREIGN KEY (`customer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `message_ibfk_7` FOREIGN KEY (`thread_id`) REFERENCES `thread` (`id`) ON DELETE CASCADE,
  CONSTRAINT `message_ibfk_8` FOREIGN KEY (`g_message_id`) REFERENCES `g_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `message_status`;
CREATE TABLE `message_status` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `g_chat_message_id` bigint(20) NOT NULL,
  `recipient_email` varchar(255) NOT NULL,
  `status` enum('sent','delivered','read') NOT NULL,
  `timestamp` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `g_chat_message_id` (`g_chat_message_id`),
  CONSTRAINT `message_status_ibfk_1` FOREIGN KEY (`g_chat_message_id`) REFERENCES `g_chat_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `presence_status`;
CREATE TABLE `presence_status` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `user_id` bigint(20) NOT NULL,
  `status` enum('online','offline','away') NOT NULL,
  `last_activity_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `presence_status_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `presence_status_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `schedule`;
CREATE TABLE `schedule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `g_schedule_id` bigint(20) NOT NULL,
  `mailbox_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `g_schedule_id` (`g_schedule_id`),
  KEY `mailbox_id` (`mailbox_id`),
  CONSTRAINT `schedule_ibfk_11` FOREIGN KEY (`mailbox_id`) REFERENCES `mailbox` (`id`) ON DELETE CASCADE,
  CONSTRAINT `schedule_ibfk_8` FOREIGN KEY (`g_schedule_id`) REFERENCES `g_schedule` (`id`) ON DELETE CASCADE,
  CONSTRAINT `scheduleibfk_10` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `sent_email`;
CREATE TABLE `sent_email` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) DEFAULT NULL,
  `from_name` varchar(255) NOT NULL,
  `from_email` varchar(255) NOT NULL,
  `to_name` varchar(255) NOT NULL,
  `to_email` varchar(255) NOT NULL,
  `preferred_language` varchar(2) NOT NULL,
  `template_name` varchar(255) NOT NULL,
  `language` varchar(2) NOT NULL,
  `parameters` text NOT NULL,
  `bcc_email` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `body` text NOT NULL,
  `status` varchar(255) NOT NULL,
  `status_message` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `to_email` (`to_email`),
  CONSTRAINT `sent_email_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `thread`;
CREATE TABLE `thread` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `folder_id` bigint(20) NOT NULL,
  `g_thread_id` bigint(20) NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `g_thread_id` (`g_thread_id`),
  KEY `folder_id` (`folder_id`),
  CONSTRAINT `thread_ibfk_5` FOREIGN KEY (`customer_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `thread_ibfk_6` FOREIGN KEY (`folder_id`) REFERENCES `folder` (`id`) ON DELETE CASCADE,
  CONSTRAINT `thread_ibfk_7` FOREIGN KEY (`g_thread_id`) REFERENCES `g_thread` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `typing_indicator`;
CREATE TABLE `typing_indicator` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `g_chat_id` bigint(20) NOT NULL,
  `user_id` bigint(20) NOT NULL,
  `started_at` datetime NOT NULL DEFAULT current_timestamp(),
  `expires_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `g_chat_id` (`g_chat_id`),
  KEY `user_id` (`user_id`),
  KEY `expires_at` (`expires_at`),
  CONSTRAINT `typing_indicator_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `typing_indicator_ibfk_2` FOREIGN KEY (`g_chat_id`) REFERENCES `g_chat` (`id`) ON DELETE CASCADE,
  CONSTRAINT `typing_indicator_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `token`;
CREATE TABLE `token` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `user_id` bigint(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `value` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `validated_at` datetime NOT NULL DEFAULT current_timestamp(),
  `used_at` datetime DEFAULT NULL,
  `valid_until` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `value` (`value`),
  KEY `customer_id` (`customer_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `token_ibfk_4` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `token_ibfk_5` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NOT NULL,
  `username` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `is_admin` int(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `modified_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `user_ibfk_3` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_ibfk_4` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

SET foreign_key_checks = 1;
